const SUPABASE_ANON_KEY = 'sb_publishable_CGWXuZ4ltyGgpzV-IpZ_Nw_pa3iuLRo';



/* الفئات المستهدفة — كما وردت في ملف البرنامج */
const CATEGORIES = [
  'طلبة الجامعات',
  'رواد الأعمال',
  'المهتمين بقطاع البلديات',
  'المهتمين بقطاعات الصناعة',
];


/* ============================================================
   شعارات الجهتين — مضمّنة داخل الملف حتى لا تعتمد الصفحات
   على ملفات صور خارجية، ولضمان ظهورها عند تصدير الشهادة PDF
   ============================================================ */
const LOGOS = {
  'qu': 'data:image/png;base64,',
  'mim': 'data:image/png;base64,',
  'qu-dark': 'data:image/png;base64,',
  'mim-dark': 'data:image/png;base64,',
};

/* تعبئة أي <img data-logo="qu"> تلقائيًا */
function paintLogos(root){
  (root || document).querySelectorAll('img[data-logo]').forEach(img => {
    const src = LOGOS[img.getAttribute('data-logo')];
    if(src) img.src = src;
  });
}
if(document.readyState === 'loading')
  document.addEventListener('DOMContentLoaded', () => paintLogos());
else paintLogos();

let supabaseClient = null;
try {
  supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: false },
  });
} catch (e) {
  console.error('تعذّر تحميل مكتبة Supabase — تحقّق من الاتصال بالإنترنت.', e);
}
